import{_ as o,a0 as i,w as l,s as m,I as a,x as r,ao as n,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"KDE 的19年进化历程 | LCTT x X-CMD","titleTemplate":false,"description":"KDE 的19年进化历程 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE 的19年进化历程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE 的19年进化历程 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20101020 19 Years of KDE History--Step by Step","title":"KDE 的19年进化历程","tag":"201601","desc":""},"relativePath":"201601/20101020 19 Years of KDE History--Step by Step.md","filePath":"[post].md"}'),g={name:"201601/20101020 19 Years of KDE History--Step by Step.md"};function u(K,t,D,c,h,E){const p=i("Link");return l(),m("div",null,[t[18]||(t[18]=a("h1",{id:"kde-的19年进化历程",tabindex:"-1"},[r("KDE 的19年进化历程 "),a("a",{class:"header-anchor",href:"#kde-的19年进化历程","aria-label":"Permalink to “KDE 的19年进化历程”"},"​")],-1)),t[19]||(t[19]=a("p",null,"注：youtube 视频",-1)),t[20]||(t[20]=a("iframe",{width:"660",height:"371",src:"https://www.youtube.com/embed/1UG4lQOMBC4?feature=oembed",frameborder:"0",allowfullscreen:""},null,-1)),t[21]||(t[21]=n('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>KDE – 史上功能最强大的桌面环境之一；开源且可自由使用。19年前，1996年10月14日，德国程序员 Matthias Ettrich 开始了这个美观的桌面环境的开发。KDE 提供了用户界面以及其他很多日常使用的程序。今日，KDE 被成千上万人在 Unix 和 Windows 上使用。19年，一个对软件项目而言极为漫长的年岁。现在是时候让我们回到最初，看看这一切肇始于何处。</p><p>K Desktop Environment（KDE）有很多创新之处：新设计，美观，一致的体验，易于使用，对普通用户和专业用户都足够强大的应用库。“KDE”这个名字是对单词“通用桌面环境”（Common Desktop Environment）玩的一个简单谐音游戏，“K”即“Cool”。 第一代 KDE 在双许可证授权下使用了 Trolltech 公司专利的 Qt framework（现 Qt 的前身），这两个许可证分别是开源的 QPL（Q public license）和商业专利许可证（proprietary commercial license）。在2000年 Trolltech 公司让一部分 Qt 软件库开始发布在 GPL 证书下; Qt 4.5 发布在了 LGPL 2.1 许可证下。自2009起 KDE 桌面环境由三部分构成：Plasma Workspaces（用做交互界面），KDE Applications，作为 KDE Software 编译的 KDE Platform。</p><h2 id="各发布版本" tabindex="-1">各发布版本 <a class="header-anchor" href="#各发布版本" aria-label="Permalink to “各发布版本”">​</a></h2><h3 id="预发布版本-–-1996年10月14日" tabindex="-1">预发布版本 – 1996年10月14日 <a class="header-anchor" href="#预发布版本-–-1996年10月14日" aria-label="Permalink to “预发布版本 – 1996年10月14日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/0b3.png" alt=""></p><p>当时名称为 Kool Desktop Environment；“Kool”这个单词在很快就被弃用了。最初，所有 KDE 的组件都是被单独发布在开发社区里的，它们并没有被一个大的项目所贯穿起来。开发组邮件列表中的首选通信是发往kde@fiwi02.wiwi.uni-Tubingen.de 邮件列表。</p><h3 id="kde-1-0-–-1998年7月12日" tabindex="-1">KDE 1.0 – 1998年7月12日 <a class="header-anchor" href="#kde-1-0-–-1998年7月12日" aria-label="Permalink to “KDE 1.0 – 1998年7月12日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/10.png" alt=""></p><p>这个版本受到了颇有争议的反馈。很多人反对使用 Qt 框架，因为当时的 FreeQt 许可证和自由软件许可证并不兼容，他们建议开发组使用 Motif 或者 LessTif 替代。尽管有着这些反对声，KDE 仍然被很多用户所青睐，并且成功作为第一个 Linux 发行版的环境被集成了进去。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/11.png" alt="28 January 1999"></p><p><em>1999年1月28日</em></p><p>有一次升级，<strong>K Desktop Environment 1.1</strong>，更快，更稳定的同时加入了很多小的改进。这个版本同时也加入了很多新的图标，背景和材质纹理。和这些全面翻新同时出现的还有 Torsten Rahn 绘制的全新 KDE 图标----一个放在齿轮前的字母 K ；这个图标的修改版也一直沿用至今。</p><h3 id="kde-2-0-–-2000年10月23日" tabindex="-1">KDE 2.0 – 2000年10月23日 <a class="header-anchor" href="#kde-2-0-–-2000年10月23日" aria-label="Permalink to “KDE 2.0 – 2000年10月23日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/20.png" alt=""></p><p>重大更新：</p><ul><li>DCOP (Desktop COmmunication Protocol)，一个端到端的通信协议</li><li>KIO，一个应用程序 I/O 库</li><li>KParts，组件对象模型</li><li>KHTML，一个符合 HTML 4.0 标准的渲染绘制引擎。</li></ul><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/21.png" alt="26 February 2001"></p><p><em>2001年2月26日</em></p><p><strong>K Desktop Environment 2.1</strong> 首次发布了媒体播放器 noatun，它使用了模组化、插件设计。为了便利开发者，K Desktop Environment 2.1 打包了 KDevelop。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/22.png" alt="15 August 2001"></p><p><em>2001年8月15日</em></p><p><strong>KDE 2.2</strong>版本在 GNU/Linux 上加快了50%的应用启动速度，同时提高了 HTML 渲染、JavaScript 稳定性和性能，同时还增加了一些 KMail 的功能。</p><h3 id="kde-3-0-–-2002年4月3日" tabindex="-1">KDE 3.0 – 2002年4月3日 <a class="header-anchor" href="#kde-3-0-–-2002年4月3日" aria-label="Permalink to “KDE 3.0 – 2002年4月3日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/30.png" alt=""></p><p>K Desktop Environment 3.0 加入了更好的限制使用功能，这个功能在电话亭、网咖，企业公用电脑上被广泛需求，它可以禁止用户完全使用软件的某些能力。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/31.png" alt="28 January 2003"></p><p><em>2003年1月28日</em></p><p><strong>K Desktop Environment 3.1</strong> 加入了新的默认窗口（Keramik）和图标样式（Crystal）和其他一些改进。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/32.png" alt="3 February 2004"></p><p><em>2004年2月3日</em></p><p><strong>K Desktop Environment 3.2</strong> 加入了诸如在网页表格、书写邮件中拼写检查的新功能；增强了邮件和日历功能。完善了 Konqueror 中的标签机制和对 Microsoft Windows 桌面共享协议（RDP）的支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/33.png" alt="19 August 2004"></p><p><em>2004年8月19日</em></p><p><strong>K Desktop Environment 3.3</strong> 侧重于组合不同的桌面组件。Kontact 被放进了群件应用 Kolab 并与 Kpilot 结合。Konqueror 的加入让 KDE 有了更好的 IM 交流功能，比如支持发送文件，以及其他 IM 协议（如IRC）的支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/34.png" alt="16 March 2005"></p><p><em>2005年3月16日</em></p><p><strong>K Desktop Environment 3.4</strong> 侧重于提高易用性。这次更新为 Konqueror、Kate、KPDF 加入了文字-语音转换功能；也在桌面系统中加入了独立的 KSayIt 文字-语音转换软件。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/35.png" alt="29 November 2005"></p><p><em>2005年11月29日</em></p><p><strong>The K Desktop Environment 3.5</strong> 发布加入了 SuperKaramba，为桌面环境提供了易于安装的插件（widgets）机制。 Konqueror 加入了广告屏蔽功能并成为了有史以来第二个通过 Acid2 CSS 测试的浏览器。</p><h3 id="kde-sc-4-0-–-2008年1月11日" tabindex="-1">KDE SC 4.0 – 2008年1月11日 <a class="header-anchor" href="#kde-sc-4-0-–-2008年1月11日" aria-label="Permalink to “KDE SC 4.0 – 2008年1月11日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/400.png" alt=""></p><p>大部分的开发投身于把最新的技术和开发框架整合进 KDE 4 当中。Plasma 和 Oxygen 是两次最大的用户界面风格变更。同时，Dolphin 替代 Konqueror 成为默认文件管理器，Okular 成为了默认文档浏览器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/401.png" alt="29 July 2008"></p><p><em>2008年7月29日</em></p><p><strong>KDE 4.1</strong> 引入了一个在 PIM 和 Kopete 中共享使用的表情主题系统；引入了可以让用户便利地从互联网上一键下载数据的 DXS。同时引入了 GStreamer、QuickTime 和 DirectShow 9 Phonon 后端。加入了新应用如：</p><ul><li>Dragon Player</li><li>Kontact</li><li>Skanlite — 扫描仪软件</li><li>Step —— 物理模拟软件</li><li>新游戏: Kdiamond、Kollision、KBreakout 和更多......</li></ul><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/402.png" alt="27 January 2009"></p><p><em>2009年1月27日</em></p><p><strong>KDE 4.2</strong> 被认为是在已经极佳的 KDE 4.1 基础上的又一次全面超越，同时也成为了大多数用户替换旧 3.5 版本的完美选择。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/403.png" alt="4 August 2009"></p><p><em>2009年8月4日</em></p><p><strong>KDE 4.3</strong> 修复了超过10000个 bug，同时加入了让近2000个用户要求的功能。整合一些新的技术例如：PolicyKit、NetworkManage &amp; Geolocation services 等也是这个版本的一大重点。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/404.png" alt="9 February 2010"></p><p><em>2010年2月9日</em></p><p><strong>KDE SC 4.4</strong> 基于 Qt 4 toolkit 的 4.6 版本，加入新的应用 KAddressBook。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/405.png" alt="10 August 2010"></p><p><em>2010年8月10日</em></p><p><strong>KDE SC 4.5</strong> 增加了一些新特性：整合了开源的浏览器引擎 WebKit 库，其现在也在 Apple Safari 和 Google Chrome 中广泛使用。KPackageKit 替换了 Kpackage。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/406.png" alt="26 January 2011"></p><p><em>2011年1月26日</em></p><p><strong>KDE SC 4.6</strong> 加强了 OpenGl 的性能，同时照常更新了无数bug和小改进。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/407.png" alt="27 July 2011"></p><p><em>2011年7月27日</em></p><p><strong>KDE SC 4.7</strong> 升级 KWin 以兼容 OpenGL ES 2.0 ，更新了 Qt Quick，Plasma Desktop 带来许多增强和在应用里的大量新特性， 修复了1.2万个 bug。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/408.png" alt="25 January 2012"></p><p><em>2012年1月25日</em></p><p><strong>KDE SC 4.8</strong>: 更好的 KWin 性能与 Wayland 支持，更崭新的 Doplhin 的外观设计。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/409.png" alt="1 August 2012"></p><p><em>2012年8月1日</em></p><p><strong>KDE SC 4.9</strong>: 向 Dolphin 文件管理器增加了一些更新，比如重新加入了实时文件重命名，鼠标辅助按钮支持，更好的位置面板和更多文件分类管理功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/410.png" alt="6 February 2013"></p><p><em>2013年2月6日</em></p><p><strong>KDE SC 4.10</strong>: 很多 Plasma 插件使用 QML 重写； Nepomuk、Kontact 和 Okular 得到了很大程度的性能和功能提升。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/411.png" alt="14 August 2013"></p><p><em>2013年8月14日</em></p><p><strong>KDE SC 4.11</strong>: Kontact 和 Nepomuk 有了很多优化。 第一代 Plasma Workspaces 进入了单纯维护阶段。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/412.png" alt="18 December 2013"></p><p><em>2013年12月18日</em></p><p><strong>KDE SC 4.12</strong>: Kontact 得到了极大的提升，包括许多小的改进。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/413.png" alt="16 April 2014"></p><p><em>2014年4月16日</em></p><p><strong>KDE SC 4.13</strong>: Nepomuk 语义搜索功能替代了桌面上的原有的 Baloo 搜索。 KDE SC 4.13 以53个语言版本发布。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/414.png" alt="20 August 2014"></p><p><em>2014年8月20日</em></p><p><strong>KDE SC 4.14</strong>: 这个发布版本侧重于稳定性提升：大量的 bug 修复和增加了一些小的功能。这是最后一个 KDE SC 4 发布版本。</p><h3 id="kde-plasma-5-0-–-2014年7月15日" tabindex="-1">KDE Plasma 5.0 – 2014年7月15日 <a class="header-anchor" href="#kde-plasma-5-0-–-2014年7月15日" aria-label="Permalink to “KDE Plasma 5.0 – 2014年7月15日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/500.png" alt=""></p><p>KDE Plasma 5 – 第五代 KDE。大幅改进了设计和系统，新的默认主题 Breeze 完全迁移到了 QML，更好的 OpenGL 性能，更完美的 HiDPI （高分辨率）显示支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/501.png" alt="11 November 2014"></p><p><em>2014年11月11日</em></p><p><strong>KDE Plasma 5.1</strong>：迁移了从 Plasma 4 里丢失的功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/502.png" alt="27 January 2015"></p><p><em>2015年1月27日</em></p><p><strong>KDE Plasma 5.2</strong>：新组件：BlueDevil、KSSHAskPass、Muon、SDDM 主题设置、KScreen、GTK+ 样式设置和 KDecoration。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/503.png" alt="28 April 2015"></p><p><em>2015年4月28日</em></p><p><strong>KDE Plasma 5.3</strong>：Plasma Media Center 技术预览。新的蓝牙和触摸板小程序；改良了电源管理。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/504.png" alt="25 August 2015"></p><p><em>2015年8月25日</em></p><p><strong>KDE Plasma 5.4</strong>：Wayland 登场，新的基于 QML 的音频管理程序，一个全屏的程序启动器替代品。</p>',102)),a("p",null,[t[2]||(t[2]=r("万分感谢 ",-1)),e(p,{href:"https://www.kde.org/"},{default:s(()=>[...t[0]||(t[0]=[r("KDE",-1)])]),_:1}),t[3]||(t[3]=r(" 开发者及社区，并感谢 Wikipedia 为书写 ",-1)),e(p,{href:"https://en.wikipedia.org/wiki/KDE_Plasma_5"},{default:s(()=>[...t[1]||(t[1]=[r("概述",-1)])]),_:1}),t[4]||(t[4]=r(" 带来的帮助，同时，感谢所有读者。让我们保持自由精神（be free）并继续支持如同 KDE 一样的开源的自由软件发展。",-1))]),t[22]||(t[22]=a("hr",null,null,-1)),a("p",null,[t[6]||(t[6]=r("via: ",-1)),e(p,{href:"https://tlhp.cf/kde-history/"},{default:s(()=>[...t[5]||(t[5]=[r("https://tlhp.cf/kde-history/",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=r("作者：",-1)),e(p,{href:"https://tlhp.cf/author/paul/"},{default:s(()=>[...t[7]||(t[7]=[r("Pavlo Rudyi",-1)])]),_:1}),t[11]||(t[11]=r(" 译者：",-1)),e(p,{href:"https://github.com/Moelf"},{default:s(()=>[...t[8]||(t[8]=[r("Moelf",-1)])]),_:1}),t[12]||(t[12]=r(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=r("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原创编译，",-1)),e(p,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[r("Linux中国",-1)])]),_:1}),t[17]||(t[17]=r(" 荣誉推出",-1))])])}const k=o(g,[["render",u]]);export{b as __pageData,k as default};
